/* Booking theme · 2026-10-31. Keep the form and calendar geometry unchanged. */
:root{color-scheme:light}
header{flex-wrap:wrap;gap:16px 24px}
header .booking-help{margin-left:auto}
.booking-theme-toggle{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:10px 14px;border:1px solid #24336a40;border-radius:24px;background:transparent;color:inherit;font:inherit;font-size:13px;cursor:pointer;white-space:nowrap}
.booking-theme-toggle>span:first-child{font-size:20px;line-height:1}
.booking-theme-toggle:focus-visible{outline:3px solid #759b2b;outline-offset:4px}
:root[data-theme="dark"]{color-scheme:dark;background:#111a2c;color:#edf1fa}
:root[data-theme="dark"] body{background:#111a2c;color:#edf1fa}
:root[data-theme="dark"] header,:root[data-theme="dark"] footer{border-color:#34415b}
:root[data-theme="dark"] header>a img{filter:brightness(0) invert(1)}
:root[data-theme="dark"] h1 em{color:#b4d970}
:root[data-theme="dark"] .booking-card{background:#1b263d;border-color:#394761;box-shadow:none}
:root[data-theme="dark"] :is(.hint,.fallback,.booking-slot-intro,.booking-ready,.booking-note-toggle summary span,.booking-review__label,.booking-review__reassurance,.booking-slot-contact p,.appointment-host span,.booking-choice-summary p+p,.booking-marketing small){color:#bdc8db}
:root[data-theme="dark"] :is(.booking-note-toggle summary,.booking-choice-summary button,#booking-status.is-booking){color:#edf1fa}
:root[data-theme="dark"] .booking-card :is(input,textarea,select){background:#121d31;color:#edf1fa;border-color:#61708a;accent-color:#b4d970}
:root[data-theme="dark"] .booking-card :is(input,textarea)::placeholder{color:#aebbd0}
:root[data-theme="dark"] .booking-card input:-webkit-autofill{-webkit-text-fill-color:#edf1fa;box-shadow:0 0 0 1000px #121d31 inset;caret-color:#edf1fa}
:root[data-theme="dark"] .booking-card button{background:#344666;color:#f4f6fc}
:root[data-theme="dark"] .slots button,:root[data-theme="dark"] .booking-card .booking-periods button{background:#121d31;color:#edf1fa;border-color:#61708a}
:root[data-theme="dark"] .slots button[aria-pressed=true],:root[data-theme="dark"] .booking-card .booking-periods button[aria-pressed=true]{background:#b4d970;color:#152409;border-color:#b4d970}
:root[data-theme="dark"] :is(.booking-review,.booking-card .booking-week-nav button,.booking-card #booking-next,.booking-card #booking-retry){background:#2c3c30;color:#e9f2dd}
:root[data-theme="dark"] #booking-submit{background:#b4d970;color:#152409}
:root[data-theme="dark"] #booking-submit.is-booking{background:#2c3c30;color:#e9f2dd}
:root[data-theme="dark"] .booking-theme-toggle{border-color:#61708a}
:root[data-theme="dark"] .skip{background:#1b263d;color:#edf1fa}
:root[data-theme="dark"] .source-consent{background:#1b263d;color:#edf1fa;border-color:#61708a;box-shadow:0 8px 36px #0005}
:root[data-theme="dark"] .source-consent button{background:#2c3c30;color:#e9f2dd;border-color:#89a65b}
:root[data-theme="dark"] .source-consent-options{border-color:#61708a}
:root[data-theme="dark"] .booking-success{background:#182b27;color:#edf1fa}
:root[data-theme="dark"] .booking-success h1,:root[data-theme="dark"] .booking-success .booking-success__eyebrow{color:#b4d970}
:root[data-theme="dark"] .booking-success p{color:#d9e5de}
:root[data-theme="dark"] .booking-success__return{background:#b4d970;color:#152409}
@media(hover:hover){.booking-theme-toggle:hover{background:#95c13b18}:root[data-theme="dark"] .slots button:not([aria-pressed=true]):hover{background:#344666}}
@media(max-width:600px){header .booking-help{order:3;width:100%;margin:0}header .booking-theme-toggle{margin-left:auto}}

