// Shared preference with the main site; no tracking or network request.
const system = matchMedia('(prefers-color-scheme: dark)')
const button = document.querySelector('.booking-theme-toggle')
const saved = () => { try { return localStorage.getItem('cl_theme') } catch { return null } }
function apply(theme) {
  const dark = theme === 'dark'
  document.documentElement.dataset.theme = dark ? 'dark' : 'light'
  button.setAttribute('aria-pressed', String(dark))
  button.setAttribute('aria-label', dark ? 'Activer le mode clair' : 'Activer le mode sombre')
  button.querySelector('[data-theme-label]').textContent = dark ? 'Mode clair' : 'Mode sombre'
}
const preferred = () => ['dark','light'].includes(saved()) ? saved() : system.matches ? 'dark' : 'light'
apply(preferred())
button.addEventListener('click', () => {
  const next = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark'
  try { localStorage.setItem('cl_theme', next) } catch {}
  apply(next)
})
system.addEventListener('change', () => { if (!['dark','light'].includes(saved())) apply(preferred()) })
window.addEventListener('storage', event => { if (event.key === 'cl_theme' || event.key === null) apply(preferred()) })
